/**
 * Fact audit Round 3 (final), group F (Career Finder) — Comp B return, 2026-10-22.
 *
 * careerIndex.json / careerFamilies.json are GENERATED by scripts/build-career-index.py
 * from the owner workbook plus scripts/career-index-overrides.json. Round 3 fixed the
 * TEMPLATE problems (preparation and work model filled from title class) at the rule
 * level — new craft families, `workModelRules`, a licensed-preparation build guard —
 * merged two duplicate titles (`mergeInto`) and fixed two orientation clashes. This
 * pins the shipped values AND the overrides/build hooks that produce them, so a
 * rebuild cannot silently undo them.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { describe, it } from 'node:test';

const read = (p: string) => readFileSync(new URL(`../${p}`, import.meta.url), 'utf8').replace(/\r\n/g, '\n');

type Raw = { id: string; f: number; t: string; alt?: string[]; st: number; ori: number; wm: number; prep: number; reg?: 1; pe?: 1 };
const index = JSON.parse(read('src/data/careerIndex.json')) as {
  families: string[];
  enums: { preparation: string[]; workModel: string[]; status: string[]; orientation: string[] };
  careers: Raw[];
};
const families = JSON.parse(read('src/data/careerFamilies.json')) as { name: string; sources: string[]; count: number }[];
const ov = JSON.parse(read('scripts/career-index-overrides.json')) as {
  craftFamilies: string[]; mergeInto: Record<string, string>; workModelRules: { family: string; match: string; from: string; to: string }[];
  regulatedVariesOk: Record<string, string>; removeFamilySources: Record<string, string[]>;
};
const build = read('scripts/build-career-index.py');

const find = (t: string) => index.careers.find((x) => x.t === t);
const byTitle = (t: string) => {
  const c = find(t);
  assert.ok(c, t);
  return c;
};
const prep = (t: string) => index.enums.preparation[byTitle(t).prep];
const wm = (t: string) => index.enums.workModel[byTitle(t).wm];
const ori = (t: string) => index.enums.orientation[byTitle(t).ori];
const st = (t: string) => index.enums.status[byTitle(t).st];

const VARIES = "Varies: portfolio/experience, certificate, associate, or bachelor's pathway";
const DEGREE = "Bachelor's degree common; portfolio/certification may supplement";
const STAFF = 'Staff roles common; consulting/contract options vary';

describe('duplicates merged (owner ruling, Round 3)', () => {
  it('Sound Utility is gone and is an "also called" name of Utility Sound Technician', () => {
    assert.equal(find('Sound Utility'), undefined);
    assert.ok(byTitle('Utility Sound Technician').alt?.includes('sound utility'));
  });
  it('Dubbing Mixer is gone and is an "also called" name of Re-Recording Mixer', () => {
    assert.equal(find('Dubbing Mixer'), undefined);
    assert.ok(byTitle('Re-Recording Mixer').alt?.includes('dubbing mixer'));
  });
  it('the merge lives in the overrides and the family tally follows it', () => {
    assert.deepEqual(ov.mergeInto, { 'Sound Utility': 'Utility Sound Technician', 'Dubbing Mixer': 'Re-Recording Mixer' });
    const fi = index.families.indexOf('Film, Television & Post-Production Audio');
    assert.equal(families.find((f) => f.name === 'Film, Television & Post-Production Audio')!.count, index.careers.filter((c) => c.f === fi).length);
  });
});

describe('orientation clashes (Round 3)', () => {
  it('Assistant Music Supervisor matches Music Supervisor', () => assert.equal(ori('Assistant Music Supervisor'), ori('Music Supervisor')));
  for (const t of ['Hearing Instrument Specialist', 'Hearing-Aid Specialist', 'Hearing-Aid Fitting Specialist', 'Tinnitus Specialist — Audiology']) {
    it(`${t} is clinical, not "Science / research"`, () => assert.equal(ori(t), 'Clinical / therapeutic'));
  }
  it('Score Orchestrator / Score Arranger match Orchestrator / Arranger', () => {
    assert.equal(ori('Score Orchestrator'), ori('Orchestrator'));
    assert.equal(ori('Score Arranger'), ori('Arranger'));
  });
});

describe('preparation template (career_bachelors_degree_common)', () => {
  it('post, broadcast, podcast and archive craft engineers are no longer "bachelor’s degree common"', () => {
    for (const t of ['Scoring Engineer', 'Final Mix Engineer — Picture', 'Broadcast Audio Engineer', 'Sports Submix Engineer', 'Podcast Audio Engineer', 'Audiobook Recording Engineer', 'Audio Restoration Engineer', 'Score Mastering Engineer', 'Talking-Book Recording Engineer']) {
      assert.equal(prep(t), VARIES, t);
    }
  });
  it('the fix is the craft-family RULE, not per-title patches', () => {
    for (const f of ['Film, Television & Post-Production Audio', 'Broadcast, Radio, Sports & Streaming', 'Podcast, Audiobook, Voice & Spoken-Word Production']) {
      assert.ok(ov.craftFamilies.includes(f), f);
    }
  });
  it('real engineering degrees stay (hardware, DSP, acoustics)', () => {
    for (const t of ['Audio Hardware Engineer', 'Audio DSP Engineer', 'Noise-Control Engineer']) assert.equal(prep(t), DEGREE, t);
  });
  it('game audio programmers are software-engineering hires', () => assert.equal(prep('Game Audio Programmer'), DEGREE));
  it('research scientists carry the research line, not the generic one', () => {
    for (const t of ['Psychoacoustician', 'Auditory Neuroscientist', 'Bioacoustician', 'Acoustic Oceanographer']) {
      assert.equal(prep(t), "Bachelor's to doctorate, depending on research responsibility", t);
    }
  });
  it('conductors: a degree is the norm, not a certificate', () => assert.match(prep('Orchestra Conductor'), /^Bachelor's degree common \(often in music\)/));
});

describe('licensed roles (career_licensed_role_with_varies_prep)', () => {
  it('no licensed title carries the generic "Varies … certificate, associate" line', () => {
    const bad = index.careers.filter((c) => c.reg && index.enums.preparation[c.prep] === VARIES).map((c) => c.t);
    assert.deepEqual(bad, []);
  });
  it('the build enforces it (guard + empty allowlist)', () => {
    assert.match(build, /licensed titles with the generic Varies preparation/);
    assert.deepEqual(ov.regulatedVariesOk, {});
  });
  it('music teachers name the teaching licence; SLPAs name their programme', () => {
    assert.match(prep('Music Teacher'), /state teaching license for public-school posts/);
    assert.match(prep('Speech-Language Pathology Assistant'), /^Associate SLPA program or bachelor's in communication sciences/);
  });
  it('noise analysts: the unconfirmed licence flag is gone (CAN\'T CONFIRM)', () => {
    for (const t of ['Environmental Noise Analyst', 'Transportation Noise Analyst', 'Airport Noise Specialist']) {
      assert.equal(byTitle(t).reg, undefined, t);
      assert.equal(prep(t), DEGREE, t);
    }
  });
  it('mass-notification design is flagged (fire-alarm rules)', () => assert.equal(byTitle('Mass-Notification Audio Designer').reg, 1));
});

describe('work-model template (career_staff_roles_common)', () => {
  it('studio recording engineers are mostly freelance; assistants stay staff', () => {
    assert.equal(wm('Recording Engineer'), 'Often freelance/contract; staff roles also exist');
    assert.equal(wm('Assistant Recording Engineer'), STAFF);
  });
  it('show and tour crew are project / tour work', () => {
    for (const t of ['Front-of-House Engineer', 'Monitor Engineer', 'Guitar Technician', 'Production Stage Manager']) {
      assert.equal(wm(t), 'Project, venue, tour, or contract work common', t);
    }
  });
  it('field broadcast and podcast engineers are staff OR freelance; station engineers stay staff', () => {
    assert.equal(wm('REMI Audio Engineer'), 'Staff, freelance, or project-based depending on sector');
    assert.equal(wm('Podcast Mixing Engineer'), 'Staff, freelance, or project-based depending on sector');
    assert.equal(wm('Broadcast Maintenance Engineer'), STAFF);
  });
  it('postdocs are fixed-term; buskers are self-employed', () => {
    assert.equal(wm('Postdoctoral Researcher — Acoustics'), 'Fixed-term research appointments, usually at universities or labs');
    assert.equal(wm('Busker — Music'), 'Self-employed; local permits often required');
  });
  it('the rules live in the overrides and the build applies them', () => {
    assert.ok(ov.workModelRules.length >= 10);
    assert.match(build, /workModelRules: rule .* changed nothing/);
  });
});

describe('status, sources and heading (Round 3)', () => {
  it('product-named and adjacent titles are specialties, not occupations', () => {
    for (const t of ['QLab Programmer', 'Atmos Re-Recording Mixer', 'Audio Grant Writer']) assert.equal(st(t), 'Established specialty or employer title', t);
    assert.equal(st('Broadcast Technician'), 'Established occupation or industry role');
  });
  it('the medical ultrasound family no longer cites the NDT society', () => {
    const med = families.find((f) => f.name === 'Medical Ultrasound & Therapeutic Acoustics')!;
    assert.ok(!med.sources.includes('American Society for Nondestructive Testing'));
    assert.deepEqual(ov.removeFamilySources, { 'Medical Ultrasound & Therapeutic Acoustics': ['American Society for Nondestructive Testing'] });
  });
  it('the family list no longer claims "every kind" of audio work', () => {
    const src = read('src/screens/careerfinder/CareerFamilyListScreen.tsx');
    assert.match(src, /title="Most kinds of paid audio work"/);
    assert.doesNotMatch(src, /Every kind of paid audio work/);
  });
});
